class Balancer {
    constructor(items) {
        this.items = items;
        this.usageCounts = new Map();
    }

    select(filterFn, comparatorFn) {
        let selected = null;
        let minUsageCount = Infinity;

        const filteredItems = this.items.filter(filterFn);

        for (const item of filteredItems) {
            const usageCount = this.usageCounts.get(item) || 0;
            if (comparatorFn(usageCount, minUsageCount)) {
                selected = item;
                minUsageCount = usageCount;
            }
        }

        if (selected !== null) {
            this.usageCounts.set(selected, (this.usageCounts.get(selected) || 0) + 1);
        }

        return selected;
    }
}
